class RegionLogger {
  private static instances = new Map<string, RegionLogger>();
  private constructor(public region: string) {}

  static getInstance(region: string): RegionLogger {
    if (!this.instances.has(region)) {
      this.instances.set(region, new RegionLogger(region));
    }
    return this.instances.get(region)!;
  }
}

const logger1 = RegionLogger.getInstance("us-east"); // file A
const logger2 = RegionLogger.getInstance("us-east"); // file B
console.log(logger1 === logger2); // true, always
